import 'dart:convert';
import 'dart:io';
import 'package:naugi/data/catalog.dart';

void main() {
  final sql = StringBuffer(
    '-- Generated by dart run tool/export_seed.dart; edit catalog.dart, not this file.\n',
  );
  for (final recipe in sampleRecipes) {
    final payload = jsonEncode(recipe.toJson()).replaceAll("'", "''");
    sql.writeln(
      "insert into public.recipe_catalog(id, payload) values ('${recipe.id}', '$payload'::jsonb) on conflict(id) do update set payload = excluded.payload;",
    );
  }
  File('supabase/seed.sql').writeAsStringSync(sql.toString());
}
